import{_ as l,b as t,c as p,g as i}from"./chunks/framework.86O3EbG5.js";const b=JSON.parse('{"title":"古代汉语","description":"","frontmatter":{"title":"古代汉语","subTitle":"课后题 · 工具书","author":"oasis","date":"2026-10-22T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/gu-dai-han-yu/kehouti/1.md","filePath":"articles/gu-dai-han-yu/kehouti/1.md"}'),e={name:"articles/gu-dai-han-yu/kehouti/1.md"};function u(s,o,r,n,c,a){return t(),p("div",null,[...o[0]||(o[0]=[i('<h2 id="工具书" tabindex="-1">工具书</h2><ol><li><p>请说明下列工具书之间的差别</p><ul><li><strong>字典与词典</strong>：字典的对象是文字，解释字的形、音、义。词典的对象包含词汇和单字，解释词汇的用法和含义。</li><li><strong>类书与政书</strong>：类书罗列广泛，政书专于历代政治制度相关内容。</li><li><strong>十通与会要、会典</strong>：十通按照朝代进行记录。会要与会典是断代的。</li><li><strong>会要与会典</strong>：会要与会典都属于断代政书。会要以事类为纲。会典以官府机构为纲。</li></ul></li><li><p>常见字典、词典中标出古音的主要有哪几部？</p><ul><li>《康熙字典》《王力古汉语字典》《中华大字典》《汉语大字典》。 <ul><li>《康熙字典》《中华大字典》采用反切。</li><li>《王力古汉语字典》《汉语大字典》不仅有中古音，还标注<strong>上古韵部</strong>，不只用反切。</li></ul></li></ul></li><li><p>工具书使用实践，查询粗体字词、典故的意思。</p><ol><li><blockquote><p>不知夫射者方将修其<strong>婆卢</strong>，治其<strong>矰缴</strong>，将加己乎百仞之上，被<strong>礛磻</strong>，引微缴，折清风而抎矣。</p></blockquote><p>《战国策·楚策四》</p></li><li><blockquote><p>先王之制，大都不过<strong>参国</strong>之一。</p></blockquote><p>《左传·隐公元年》</p></li><li><blockquote><p>归<strong>谢</strong>袁本初，兄弟不能相容，而能容天下国士乎？</p></blockquote><p>《三国志·魏书·贾诩传》</p></li><li><blockquote><p>起，矫命以责赐诸民，<strong>因</strong>烧其券，民称万岁。</p></blockquote><p>《战国策·齐策》</p></li><li><blockquote><p>在晋中兴，玄风独扇，为学穷于<strong>柱下</strong>，博物止乎七篇。</p></blockquote><p>《宋书·谢灵运传论》</p></li><li><blockquote><p>仆之先非有<strong>剖符丹书</strong>之功。</p></blockquote><p>司马迁《报任安书》</p></li></ol></li></ol><h2 id="选文翻译" tabindex="-1">选文翻译</h2><ol><li><p>晏子之晋，至中牟，睹弊冠反裘负刍息于涂侧者，以为君子也。</p><blockquote><p>晏子前往晋国，走至中牟，看见</p></blockquote></li><li><p>使人问焉，曰：“子何为者也？”对曰：“我越石父者也，为人臣仆于中牟，见使将归。”</p><blockquote><p>派人问那人，说：“你是做什么的？”回答说：“我叫越石父，在中牟给人当奴仆，”</p></blockquote></li><li><p>晏子曰：“为仆几何？”对曰：“三年矣。”晏子曰：“可得赎乎？”对曰：“可。”</p><blockquote><p>晏子说：“做奴仆多久？”答：“三年了。”晏子说：“可以赎身吗？”答：“可以。”</p></blockquote></li><li><p>遂解左骖以赠之，因载与俱归。至舍，不辞而入。</p><blockquote><p>于是解开左侧的马匹赠给他。于是（让他）上车，和（晏子）一同回去。回到住处，（晏子）没有向越石父告辞，就径自进门。</p></blockquote></li><li><p>越石父怒而请绝。晏子使人应之曰：“吾未尝得交夫子也，子为仆三年，吾乃今日睹而赎之，吾于子尚未可乎？子何绝我之暴也？”</p><blockquote><p>越石父发怒，请求与晏子绝交。晏子派人答复他说：“我不曾和您结交。您做奴仆三年，我直到今日见到您，才把您赎出来。我对待您难道还不算可以吗？您为什么这么突然地要和我绝交呢？”</p></blockquote></li><li><p>越石父对曰：“臣闻之，士者诎乎不知己而申乎知己，故君子不以功轻人之身，不为被功诎身之理。吾三年为人臣仆而莫吾知也。今子赎我，吾以子为知我矣。向者子乘不我辞也，吾以子为忘。今又不辞而入，是与臣我者同矣。我犹且为臣，请鬻于世。”</p><blockquote><p>越石父回答说：“我听说，贤士在不了解自己的人面前受委屈，在了解自己的人面前才能伸展志节。所以君子不会因为自己对别人有功，就轻视别人的人格；也不会因为别人对自己有恩惠，就委屈自身的道义。我做人家的奴仆三年，没有人了解我。如今您赎回我，我本以为您是了解我的。刚才您乘车的时候，不向我告辞，我还以为您只是一时忘记。现在到家又不告辞就进门，这和把我当作奴仆看待的人没有两样。我既然仍旧如同奴仆，请允许把我卖到世间（重做奴仆）。”</p></blockquote></li><li><p>晏子出见之，曰：“向者见客之容，而今也见客之意，婴可以辞而无弃乎？婴诚革之。”</p><blockquote><p>晏子走出来，接见他，说：“刚才我只看到您的外表容貌，如今才看到您的内心志意。我能够向您谢罪，希望不被您弃绝吗？我真心改正我的过错。”</p></blockquote></li><li><p>乃令粪洒改席，尊醮而礼之。</p><blockquote><p>于是下令洒水清扫更换座席，用饮酒的礼节招待越石父。</p></blockquote></li><li><p>越石父曰：“吾闻之，至恭不修涂，尊礼不受摈。夫子礼之，仆不敢当也。”晏子遂以为上客。</p><blockquote><p>越石父说：“我听说，极致的恭敬不在外表修饰排场；遵守礼义之人，不会遭到摈弃冷落。先生您以礼待我，我不敢承受这样的礼遇。”晏子于是把他尊为上等宾客。</p></blockquote></li></ol><p>《晏子春秋·内篇·杂上》</p>',5)])])}const g=l(e,[["render",u]]);export{b as __pageData,g as default};
